"""Self-contained MLB moneyline Streamlit application.

Generated from the modular mlb-analytics-platform repository. Upload this file
as streamlit_app.py together with requirements.txt to Streamlit Community Cloud.
"""

from __future__ import annotations

import base64
import runpy
import shutil
import sys
import tempfile
from io import BytesIO
from pathlib import Path
from zipfile import ZipFile


BUNDLE_SHA256 = "2cd51f995d681b2d562ab5f029883703423ea0e2983444fc658c70f3128fc322"
BUNDLE_BASE64 = ""
ROOT = Path(__file__).resolve().parent
RUNTIME = Path(tempfile.gettempdir()) / "mlb_moneyline_streamlit_bundle"
MARKER = RUNTIME / ".bundle_version"


def prepare_runtime() -> None:
    current = MARKER.read_text(encoding="utf-8").strip() if MARKER.exists() else ""
    if current != BUNDLE_SHA256:
        if RUNTIME.exists():
            shutil.rmtree(RUNTIME)
        RUNTIME.mkdir(parents=True, exist_ok=True)
        payload = base64.b64decode(BUNDLE_BASE64.encode("ascii"))
        with ZipFile(BytesIO(payload)) as archive:
            archive.extractall(RUNTIME)
        MARKER.write_text(BUNDLE_SHA256, encoding="utf-8")
    # Seed the repository working directory only when the user has not already
    # uploaded or generated newer session data.
    data_dir = ROOT / "data"
    data_dir.mkdir(parents=True, exist_ok=True)
    for name in ["mlb_analytics.db", "reliability_snapshot.json"]:
        source = RUNTIME / "data" / name
        destination = data_dir / name
        if source.exists() and not destination.exists():
            shutil.copy2(source, destination)
    (ROOT / "models").mkdir(parents=True, exist_ok=True)


prepare_runtime()
sys.path.insert(0, str(RUNTIME / "src"))
runpy.run_path(str(RUNTIME / "app" / "Home.py"), run_name="__main__")
